insert into publishers (name) values ('Sourcegraph') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Cody', 'cody', p.id, 'AI coding assistant that uses codebase context from Sourcegraph.', 'Cody helps developers search, explain and write code with awareness of large codebases.', 'https://sourcegraph.com/cody', 'published', 'Freemium', 'Free / paid plans', false, false, false, ARRAY['codebase', 'assistant', 'sourcegraph']::text[], ARRAY['Strong codebase context']::text[], ARRAY['Best with Sourcegraph setup']::text[], ARRAY['Developers', 'Enterprises']::text[], current_date from publishers p where p.name = 'Sourcegraph' on conflict (slug) do nothing;
